28	    /** Whether an existing owner shares the candidate's whole identity key. */
29	    public static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
30	        String key = of(candidate);
31	        return existing.stream().anyMatch(o -> key.equals(of(o)));
32	    }
